<?php include "auth.php";include "conection.php";$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM kategori WHERE id_kategori=?");$q->bind_param("i",$id);$q->execute();$data=$q->get_result()->fetch_assoc();if(!$data)die("Kategori tidak ditemukan.");$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama_kategori']??'');$ket=trim($_POST['keterangan']??'');if($nama==='')$error='Nama kategori wajib diisi.';else{$s=$conn->prepare("UPDATE kategori SET nama_kategori=?,keterangan=? WHERE id_kategori=?");$s->bind_param("ssi",$nama,$ket,$id);if($s->execute()){header("Location: kategori.php");exit;}$error=$s->error;}}?>
